<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Reports | HMS</title><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Manrope:wght@700;800&display=swap" rel="stylesheet"><style>
:root{--bg:#091b35;--panel:#122b50;--raised:#1b3964;--line:#2c4770;--gold:#edbd3f;--muted:#bdc8db}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:#fff;font:14px 'DM Sans',sans-serif}.wrap{max-width:1250px;margin:auto;padding:25px 27px 45px}.top{display:flex;justify-content:space-between;align-items:center;gap:16px;margin-bottom:18px}h1,h2{font-family:Manrope,sans-serif}h1{margin:0;font-size:29px}h2{margin:0;font-size:15px}.sub{color:var(--muted);margin:6px 0}.link{color:var(--gold);text-decoration:none;border:1px solid var(--line);padding:10px 14px;border-radius:8px}.kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:16px}.kpi{padding:16px;border:1px solid var(--line);border-radius:9px;background:var(--panel)}.kpi small{color:var(--muted)}.kpi strong{display:block;margin-top:7px;color:var(--gold);font:800 24px Manrope,sans-serif}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.card{overflow:hidden;border:1px solid var(--line);border-radius:10px;background:var(--panel)}.head{padding:15px 16px;border-bottom:1px solid var(--line)}.table{overflow:auto}table{width:100%;border-collapse:collapse;font-size:12px}th,td{padding:12px 14px;border-bottom:1px solid var(--line);text-align:left}th{background:var(--raised);color:var(--gold);font-size:11px}.value{color:var(--gold);font-weight:700}.empty{text-align:center;color:var(--muted);padding:20px}@media(max-width:700px){.top{align-items:flex-start;flex-direction:column}.kpis,.grid{grid-template-columns:1fr 1fr}}@media(max-width:460px){.kpis,.grid{grid-template-columns:1fr}.wrap{padding:17px 12px}}
</style></head><body><main class="wrap"><header class="top"><div><h1>Hospital Reports</h1><p class="sub">Live summary across patients, appointments, doctors, admissions, laboratory and pharmacy.</p></div><a class="link" href="{{ url('/') }}">Dashboard</a></header><section class="kpis"><div class="kpi"><small>Total patients</small><strong>{{ number_format($kpis['patients']) }}</strong></div><div class="kpi"><small>Today's appointments</small><strong>{{ number_format($kpis['appointments']) }}</strong></div><div class="kpi"><small>Available doctors</small><strong>{{ number_format($kpis['doctors']) }}</strong></div><div class="kpi"><small>Currently admitted</small><strong>{{ number_format($kpis['admitted']) }}</strong></div></section><section class="grid"><article class="card"><div class="head"><h2>Today's clinical activity</h2></div><div class="table"><table><tbody><tr><td>Prescriptions generated</td><td class="value">{{ number_format($summary['prescriptions']) }}</td></tr><tr><td>Laboratory requests</td><td class="value">{{ number_format($summary['lab_requests']) }}</td></tr><tr><td>Confirmed appointments</td><td class="value">{{ number_format($summary['completed_appointments']) }}</td></tr><tr><td>Pharmacy sales</td><td class="value">Rs {{ number_format($summary['pharmacy_sales'], 0) }}</td></tr></tbody></table></div></article><article class="card"><div class="head"><h2>Report scope</h2></div><div class="table"><table><tbody><tr><td>Patient operations</td><td class="value">Live</td></tr><tr><td>Appointment operations</td><td class="value">Live</td></tr><tr><td>Laboratory operations</td><td class="value">Live</td></tr><tr><td>Pharmacy operations</td><td class="value">Live</td></tr></tbody></table></div></article></section></main></body></html>